import{z as E,x as p,o as s,c as P,q as n,j as o,D as r,d as A,s as l,S as i,b as e}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"ARP","description":"","frontmatter":{"title":"ARP","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/arp.md","filePath":"cs/arp.md","lastUpdated":1791413859000}'),d={name:"cs/arp.md"};function B(C,a,R,m,u,c){const t=p("Mermaid");return s(),P("div",null,[a[2]||(a[2]=n('<h1 id="arp" tabindex="-1">ARP <a class="header-anchor" href="#arp" aria-label="Permalink to &quot;ARP&quot;">​</a></h1><div class="epigraph"><p>ARP 在同一链路上问：这个 IP 对应哪一个 MAC？回答后才能把帧的目的地址填对。</p><footer>—— 据 Plummer, RFC 826, An Ethernet Address Resolution Protocol, 1982 整理</footer></div><p><a href="/cs/spanning-tree">上一课</a>让广播域在树上看可转发。<a href="/cs/frame-mac">帧与 MAC</a> 要目的硬件地址；<a href="/cs/layering-e2e">分层</a>已经预告网络层会有主机号。缺口是同一链路上 <strong>IP → MAC</strong> 的解析。本课是 ARP（RFC 826），不把子网掩码写完。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>主机要发 IP 包给「下一跳」（可能就是目的主机）。链路只认 MAC。若静态配置每台邻居，无法应对热插拔。ARP：广播「谁拥有此 IP」，拥有者单播回自己的 MAC；双方缓存。缺口不是路由算法，而是已连通链路上的翻译表。</p><p><span class="marginnote">直觉类比：ARP 像在会议室喊一嗓子「谁是张伟？报个座号」——全场都听得见（广播），只有本人举手回号（单播应答），提问的人把「张伟→座号」记进小本（缓存），下次直接按号找人。</span></p><p>ARP 无认证，应答可被冒充；安全课再谈，本课只钉解析。</p><p><span class="marginnote">缓存有超时。代理 ARP 曾让路由器替整网回答，今日少用。IPv6 改用邻居发现，对照在 IPv6 课。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>发送前查 ARP 表；无则广播请求，可先排队 IP 包。收到应答后填表，封装帧。Gratuitous ARP 用于宣告或检测冲突。交换机对 ARP 请求当广播泛洪，对单播应答则按 MAC 表走——生成树保证这不会转圈。</p><p><span class="marginnote">数字实例：主机每秒向同一网关发 1000 个包。没有缓存就得每包广播一次 ARP，广播帧还会淹到同 VLAN 每台主机；缓存 30 秒不过期，就只问一次——代价差三万倍，「解析结果必须缓存」由此而来。</span></p>',11)),(s(),o(i,null,{default:r(()=>[l(t,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20IP%5B%22%E8%A6%81%E5%B0%81%E8%A3%85%E7%9A%84%20IP%20%E5%8C%85%22%5D%20--%3E%20CACHE%5B%22%E6%9F%A5%20ARP%20%E7%BC%93%E5%AD%98%22%5D%0A%20%20CACHE%20--%3E%20HIT%5B%22%E5%A1%AB%E7%9B%AE%E7%9A%84%20MAC%22%5D%0A%20%20CACHE%20--%3E%20BCAST%5B%22%E5%B9%BF%E6%92%AD%E8%AF%B7%E6%B1%82%22%5D%0A%20%20BCAST%20--%3E%20REP%5B%22%E5%BA%94%E7%AD%94%E5%90%8E%E5%A1%AB%E8%A1%A8%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[A(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("h2",{id:"机制",tabindex:"-1"},[A("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=e("p",null,[A("ARP 把网络层名字临时接到链路层名字，让"),e("a",{href:"/cs/io-dma"},"DMA"),A(" 出去的帧能被正确网卡过滤。它是一跳协议：过了路由器，下一跳要重新 ARP，MAC 会换。端到端论证：ARP 不保证 IP 包到达最终主机，只保证「这一跳的帧头填对」。")],-1)),a[5]||(a[5]=e("p",null,[e("span",{class:"marginnote"},"常见误区：初学者容易以为帧里的 MAC 像 IP 一样从源到目的不变。实际上 MAC 只管一跳，过一台路由器就换一次，端到端身份在 IP 头里。排障时抓包看到 MAC「变了」不是被劫持，是过了网关。")],-1)),(s(),o(i,null,{default:r(()=>[l(t,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20LR%0A%20%20H%5B%22%E4%B8%BB%E6%9C%BA%20A%22%5D%20--%3E%7C%22%E5%B8%A7%E5%A4%B4%20dst%20MAC%20%3D%20R1%22%7C%20R1%5B%22%E8%B7%AF%E7%94%B1%E5%99%A8%20R1%22%5D%0A%20%20R1%20--%3E%7C%22%E5%B8%A7%E5%A4%B4%20dst%20MAC%20%3D%20R2%2C%20%E6%AF%8F%E8%B7%B3%E9%87%8D%E6%96%B0%20ARP%22%7C%20R2%5B%22%E8%B7%AF%E7%94%B1%E5%99%A8%20R2%22%5D%0A%20%20R2%20--%3E%7C%22%E5%B8%A7%E5%A4%B4%20dst%20MAC%20%3D%20B%22%7C%20B%5B%22%E4%B8%BB%E6%9C%BA%20B%22%5D%0A%20%20IP%5B%22IP%20%E5%A4%B4%3A%20src%20A%2C%20dst%20B%2C%20%E5%85%A8%E7%A8%8B%E4%B8%8D%E5%8F%98%22%5D%20-.-%3E%20H%0A%20%20IP%20-.-%3E%20B%0A"})]),fallback:r(()=>[...a[1]||(a[1]=[A(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=n('<p>与进程：ARP 在内核网络栈，不经用户<a href="/cs/signals">信号</a>；用户只看见套接字发送成功或主机不可达（后课 ICMP）。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 NDP 选项清单，不把 InfiniBand 的 GID 解析混进来。也不把静态 ARP 当安全方案。IP 自己如何编号、何为子网，那是后面编址与子网一课的事；没有子网，就还不知道「是否同一链路、要不要 ARP 目的还是 ARP 网关」。</p><p>同一 IP 被两台主机声明时，后到的应答会污染缓存。检测靠 gratuitous；本课不把防御写成配置指南。</p><p>后课默认：同一链路上能把 IP 译成 MAC。哪些 IP 算同一链路，是后面<a href="/cs/ip-subnet">编址与子网</a>一课的缺口。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>ARP 在以太网链路上解析 IP 到 MAC（RFC 826）。</li><li>缓存、广播请求、单播应答；每跳可重新解析。</li><li>子网决定问谁，是后面<a href="/cs/ip-subnet">编址与子网</a>一课的缺口。</li><li>出处：RFC 826；Kurose and Ross；Tanenbaum <em>Computer Networks</em>。</li></ul>',7))])}const I=E(d,[["render",B]]);export{f as __pageData,I as default};
